python3 -c "import json; from datetime import datetime, timezone; import dateutil.parser; f=open('ledger.json'); rows=json.load(f); f.close(); prod_id='account-203'; utc_start=datetime(2026,6,1,0,0,0,tzinfo=timezone.utc); utc_end=datetime(2026,7,1,0,0,0,tzinfo=timezone.utc); latest_rev=dict();
for r in rows:
    k=r['event_id']; rev=int(r['revision']);
    if k not in latest_rev or rev > latest_rev[k]['revision']:
        latest_rev[k]=r

def is_valid(row):
    return row['customer_id']==prod_id and row['status']=='settled' and utc_start<=dateutil.parser.isoparse(row['occurred_at'])<utc_end

filtered=[row for row in latest_rev.values() if is_valid(row)]
totals={}; ids=[];
for row in filtered:
    ids.append(row['event_id']); c=row['currency']; a=row['amount_minor']
    if c not in totals: totals[c]=0
    if row['kind']=='capture': totals[c] += a
    elif row['kind']=='refund': totals[c] -= a
result={'totals_minor':totals,'included_event_ids':sorted(set(ids))}
json.dump(result,open('report.json','w'))"
